commands:
{ <iptables> -C f2b-a -j RETURN >/dev/null 2>&1; } || { <iptables> -N f2b-a || true; <iptables> -A f2b-a -j RETURN; }
for chain in $(echo 'INPUT' | sed 's/,/ /g'); do for proto in $(echo 'tcp' | sed 's/,/ /g'); do
{ <iptables> -C $chain -p $proto --dport ssh -j f2b-a >/dev/null 2>&1; } || { <iptables> -I $chain -p $proto --dport ssh -j f2b-a; }
done; done

{ <iptables> -C f2b-b -j RETURN >/dev/null 2>&1; } || { <iptables> -N f2b-b || true; <iptables> -A f2b-b -j RETURN; }
for chain in $(echo 'INPUT' | sed 's/,/ /g'); do for proto in $(echo 'tcp' | sed 's/,/ /g'); do
{ <iptables> -C $chain -p $proto -m multiport --dports ssh -j f2b-b >/dev/null 2>&1; } || { <iptables> -I $chain -p $proto -m multiport --dports ssh -j f2b-b; }
done; done

{ nft -a list chain inet f2b-table f2b-chain | sed -nE 's/.*@<addr_set>\s+.*\s+\#\s*(handle\s+[0-9]+)$/\1/p'; } | while read -r hdl; do
nft delete rule inet f2b-table f2b-chain $hdl; done
nft delete set inet f2b-table <addr_set>
{ nft list table inet f2b-table | grep -qE '^\s+set\s+'; } || {
nft delete table inet f2b-table
}
